var RenovationInvoices=(()=>{
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n==null?'Betrag noch offen':new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);let cfg,context,selected=null,busy=false,uploading=false,refreshId=0;
const message=s=>{$('invoice-message').textContent=s;if($('invoice-panel-message'))$('invoice-panel-message').textContent=s};
function status(meta){return meta.status==='paid'?'Bezahlt':'Zahlung ausstehend'}
function card(meta){return `<article class="invoice-card"><div><strong>${esc(meta.fileName)}</strong><small>${esc(meta.planName)} · ${esc(meta.targetName)}</small><small>${esc(meta.supplier||'Lieferant noch offen')}${meta.invoiceNumber?' · '+esc(meta.invoiceNumber):''}${meta.date?' · '+esc(meta.date):''}</small></div><span class="invoice-status ${meta.status==='paid'?'paid':'pending'}">${status(meta)}</span><strong>${money(meta.total)}</strong><div class="invoice-actions"><button type="button" data-invoice-review="${esc(meta.id)}">Prüfen / Daten übernehmen</button><button type="button" data-invoice-download="${esc(meta.id)}">Herunterladen</button><button type="button" data-invoice-payment="${esc(meta.id)}">${meta.status==='paid'?'Als ausstehend markieren':'Als bezahlt markieren'}</button><button type="button" data-invoice-delete="${esc(meta.id)}">Entfernen</button></div>${meta.analysisError?`<p class="invoice-warning">${esc(meta.analysisError)} Angaben können manuell ergänzt werden.</p>`:''}</article>`}
async function refresh(){if(!cfg)return;const token=++refreshId;try{const all=await InvoiceStore.all();if(token!==refreshId)return;const p=cfg.getPlan(),list=$('invoice-all-plans').checked?all:all.filter(x=>x.planId===p.id),filter=$('invoice-status-filter').value,visible=list.filter(x=>!filter||(x.status==='paid'?'paid':'pending')===filter);$('invoice-summary').textContent=list.filter(x=>x.status!=='paid').length+' Zahlung ausstehend · '+list.filter(x=>x.status==='paid').length+' bezahlt';$('invoice-list').innerHTML=visible.map(card).join('')||'<p>Noch keine passenden Rechnungen. Belege kannst du über „Rechnungen“ an einem To-do, Material oder Werkzeug hochladen.</p>';if(context)$('invoice-target-list').innerHTML=all.filter(x=>x.planId===context.planId&&x.targetType===context.type&&x.targetId===context.id).map(card).join('')||'<p>Für diese Kostenposition sind noch keine Belege hinterlegt.</p>';document.querySelectorAll('[data-invoice-target]').forEach(button=>{const matching=all.filter(x=>x.planId===p.id&&x.targetId===button.dataset.invoiceTarget&&x.targetType===button.dataset.invoiceType),pending=matching.filter(x=>x.status!=='paid').length;button.textContent='Rechnungen'+(matching.length?' ('+matching.length+(pending?' · '+pending+' offen':'')+')':'')})}catch(e){message(e.message)}}
async function openTarget(type,id){if(busy||uploading){message('Bitte die laufende Rechnungsauswertung abwarten.');return}const p=cfg.getPlan();if(!p.id){cfg.requireSave();return}const target=(type==='task'?p.tasks:p.resources).find(x=>x.id===id);if(!target)return;context={planId:p.id,planName:p.name,type,id,name:target.title||target.label};$('invoice-target-name').textContent=context.name;$('invoice-details').hidden=true;selected=null;$('invoice-message').textContent='';$('invoice-dialog').showModal();await refresh()}
async function hash(file){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function validate(file){if(!file.size||file.size>20*1024*1024)throw Error('Bitte eine Datei bis 20 MB auswählen.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer()),pdf=String.fromCharCode(...bytes.slice(0,5))==='%PDF-',png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,jpg=bytes[0]===255&&bytes[1]===216,webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!pdf&&!png&&!jpg&&!webp)throw Error('Unterstützt werden PDF, JPG, PNG und WebP.');return pdf?'application/pdf':png?'image/png':jpg?'image/jpeg':'image/webp'}
async function analyze(meta,file){busy=true;$('invoice-files').disabled=true;try{message('Rechnung wird lokal ausgelesen …');meta.text=(await InvoiceReader.extract(file,message)).slice(0,250000);const parsed=InvoiceCore.parse(meta.text);Object.assign(meta,parsed,{analysisError:'',analyzedAt:new Date().toISOString()});const current=await InvoiceStore.get(meta.id);if(!current)return;meta.status=current.status;meta.paidAt=current.paidAt;meta.applications=current.applications||[];await InvoiceStore.put(meta);await review(meta.id);message(parsed.positions.length+' Position(en) erkannt. Bitte Angaben und Netto/Brutto prüfen, bevor du Werte übernimmst.')}catch(e){meta.analysisError='Automatisches Auslesen nicht vollständig: '+e.message;const current=await InvoiceStore.get(meta.id);if(!current)return;meta.status=current.status;meta.paidAt=current.paidAt;meta.applications=current.applications||[];await InvoiceStore.put(meta);await review(meta.id);message(meta.analysisError)}finally{busy=false;$('invoice-files').disabled=uploading;await refresh()}}
async function upload(files){if(!context||busy||uploading)return;uploading=true;$('invoice-files').disabled=true;try{for(const original of [...files].slice(0,10)){try{const type=await validate(original),file=new File([original],original.name,{type}),digest=await hash(file),existing=(await InvoiceStore.all()).find(x=>x.planId===context.planId&&x.targetType===context.type&&x.targetId===context.id&&x.hash===digest);if(existing){await review(existing.id);message('Diese Datei ist dieser Kostenposition bereits zugeordnet.');continue}const meta={id:crypto.randomUUID(),planId:context.planId,planName:context.planName,targetType:context.type,targetId:context.id,targetName:context.name,fileName:file.name,fileType:type,size:file.size,hash:digest,uploadedAt:new Date().toISOString(),status:'pending',paidAt:null,supplier:'',invoiceNumber:'',date:'',total:null,text:'',positions:[],applications:[]};await InvoiceStore.add(meta,file);await analyze(meta,file)}catch(e){message(e.message)}}}finally{uploading=false;$('invoice-files').disabled=false;$('invoice-files').value=''}}
function fillPosition(index){const p=selected?.positions?.[index]||{};$('invoice-item-label').value=p.label||'';$('invoice-item-qty').value=p.qty??'';$('invoice-item-unit').value=p.unit||'';$('invoice-item-price').value=p.unitPrice??'';$('invoice-item-basis').value=p.basis||'unknown';$('invoice-item-vat').value=p.vat??''}
async function review(id){const meta=await InvoiceStore.get(id);if(!meta)return;if(!context||context.planId!==meta.planId||context.id!==meta.targetId){context={planId:meta.planId,planName:meta.planName,type:meta.targetType,id:meta.targetId,name:meta.targetName};$('invoice-target-name').textContent=context.name}selected=meta;$('invoice-details').hidden=false;$('invoice-file-name').textContent=meta.fileName;$('invoice-supplier').value=meta.supplier||'';$('invoice-number').value=meta.invoiceNumber||'';$('invoice-date').value=meta.date||'';$('invoice-total').value=meta.total??'';$('invoice-payment-status').value=meta.status==='paid'?'paid':'pending';$('invoice-text').value=meta.text||'';$('invoice-position').innerHTML='<option value="">Manuell ergänzen / Gesamtbetrag</option>'+(meta.positions||[]).map((p,i)=>`<option value="${i}">${esc(p.label)} · ${p.qty??'?'} ${esc(p.unit)} · ${money(p.unitPrice)}</option>`).join('');$('invoice-position').value=meta.positions?.length?'0':'';fillPosition(meta.positions?.length?0:-1);if(!$('invoice-dialog').open)$('invoice-dialog').showModal();await refresh()}
function fields(){return {label:$('invoice-item-label').value,qty:InvoiceCore.number($('invoice-item-qty').value),unit:$('invoice-item-unit').value,unitPrice:InvoiceCore.number($('invoice-item-price').value),basis:$('invoice-item-basis').value,vat:InvoiceCore.number($('invoice-item-vat').value)}}
async function saveMeta(){if(!selected)return;selected.supplier=$('invoice-supplier').value.trim();selected.invoiceNumber=$('invoice-number').value.trim();selected.date=$('invoice-date').value;selected.total=InvoiceCore.number($('invoice-total').value);const next=$('invoice-payment-status').value==='paid'?'paid':'pending';selected.status=next;selected.paidAt=next==='paid'?(selected.paidAt||new Date().toISOString()):null;const index=$('invoice-position').value;if(index!=='')selected.positions[Number(index)]=fields();selected.text=$('invoice-text').value.slice(0,250000);await InvoiceStore.put(selected);await refresh()}
function init(options){cfg=options;document.addEventListener('click',async event=>{const b=event.target.closest('[data-invoice-target],[data-invoice-review],[data-invoice-download],[data-invoice-payment],[data-invoice-delete]');if(!b)return;try{if(b.dataset.invoiceTarget){await openTarget(b.dataset.invoiceType,b.dataset.invoiceTarget);return}const id=b.dataset.invoiceReview||b.dataset.invoiceDownload||b.dataset.invoicePayment||b.dataset.invoiceDelete;if(b.dataset.invoiceReview){if(busy||uploading){message('Bitte die Auswertung abwarten.');return}await review(id)}else if(b.dataset.invoiceDownload){const meta=await InvoiceStore.get(id),file=await InvoiceStore.file(id);if(!file)throw Error('Datei nicht mehr verfügbar.');const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=meta.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}else if(b.dataset.invoicePayment){if(busy||uploading){message('Bitte die Auswertung abwarten.');return}const meta=await InvoiceStore.get(id);meta.status=meta.status==='paid'?'pending':'paid';meta.paidAt=meta.status==='paid'?new Date().toISOString():null;await InvoiceStore.put(meta);if(selected?.id===id){selected.status=meta.status;selected.paidAt=meta.paidAt;$('invoice-payment-status').value=meta.status};await refresh()}else if(b.dataset.invoiceDelete){if(busy||uploading){message('Bitte die Auswertung abwarten.');return}if(confirm('Diesen lokal gespeicherten Beleg samt Datei entfernen? Bereits übernommene Kosten bleiben im Plan.')){await InvoiceStore.remove(id);if(selected?.id===id){selected=null;$('invoice-details').hidden=true}await refresh()}}}catch(e){message(e.message)}});
$('invoice-files').onchange=e=>upload(e.target.files);$('invoice-close').onclick=()=>$('invoice-dialog').close();$('invoice-save').onclick=async()=>{if(busy||uploading)return;try{await saveMeta();message('Rechnungsangaben und Zahlungsstatus gespeichert.')}catch(e){message(e.message)}};$('invoice-position').onchange=()=>fillPosition($('invoice-position').value===''?-1:Number($('invoice-position').value));$('invoice-reparse').onclick=async()=>{if(!selected||busy||uploading)return;try{const parsed=InvoiceCore.parse($('invoice-text').value);selected.positions=parsed.positions;selected.text=$('invoice-text').value;await InvoiceStore.put(selected);await review(selected.id);message('Text erneut ausgewertet. Bitte Positionen prüfen.')}catch(e){message(e.message)}};
$('invoice-apply').onclick=async()=>{if(busy||uploading)return;try{if(!selected)return;if(cfg.getPlan().id!==selected.planId)throw Error('Bitte zuerst den zugehörigen Renovierungsplan öffnen.');const values=InvoiceCore.applyValues(fields());if(!confirm('Menge '+values.qty+' '+values.unit+' und Brutto-Einzelpreis '+money(values.unitPrice)+' in die Kostenposition übernehmen? Vorhandene Mengen und Preise werden ersetzt.'))return;if(!cfg.apply(selected.targetType,selected.targetId,values))throw Error('Die Kostenposition existiert in diesem Plan nicht mehr.');await saveMeta();selected.applications||=[];selected.applications.push({at:new Date().toISOString(),...values});await InvoiceStore.put(selected);message('Werte im geöffneten Plan übernommen. Bitte den Renovierungsplan speichern.')}catch(e){message(e.message)}};
$('invoice-retry').onclick=async()=>{if(busy||!selected)return;const file=await InvoiceStore.file(selected.id);if(file)await analyze(selected,file)};$('invoice-use-total').onclick=()=>{const total=InvoiceCore.number($('invoice-total').value);if(total===null){message('Bitte zuerst den Brutto-Gesamtbetrag eintragen.');return}$('invoice-position').value='';$('invoice-item-qty').value=1;$('invoice-item-unit').value='pauschal';$('invoice-item-price').value=total;$('invoice-item-basis').value='gross';$('invoice-item-vat').value='';message('Gesamtbetrag für eine pauschale Übernahme vorbereitet. Bitte erst bestätigen, wenn die ganze Rechnung zu dieser Kostenposition gehört.')};$('invoice-all-plans').onchange=refresh;$('invoice-status-filter').onchange=refresh;refresh()}
return {init,refresh};})();
